#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────



# What remains after the first deploy (ticket #96, spec #87), once
# scripts/aws-first-deploy-wizard.sh has run: the SNS e-mail subscription
# confirmed, a manual run of both maintenance tasks, the plantai.ia.br domain
# verified in Resend (records on the send. subdomain, in Registro.br) and the
# production EMAIL_FROM switched to PlantAí <nao-responda@plantai.ia.br>,
# ending with a real sign-up whose code arrives from that address.
#
# No secret is written to disk, to argv or to the shell history: values are
# typed hidden (read -s) and reach the AWS CLI and curl through stdin. Every
# stage checks the current state first, so a re-run skips what is done.
#
# Usage: scripts/aws-after-first-deploy-wizard.sh   (AWS_PROFILE is honored)

# Nothing goes to a .env: production values live in SSM only.
ENV_FILE=/dev/null

REGION="us-east-1"
STACK="PlantaiApi"
SSM_PREFIX="/plantai/production"
API_DOMAIN="api.plantai.ia.br"
ZONE="plantai.ia.br"
EMAIL_FROM_PRODUCTION="PlantAí <nao-responda@plantai.ia.br>"
export AWS_REGION="$REGION" AWS_DEFAULT_REGION="$REGION"

WORK_DIR=$(mktemp -d)
chmod 700 "$WORK_DIR"
trap 'rm -rf "$WORK_DIR"' EXIT

# json_string VALUE: VALUE as a JSON string literal (builtins only, so the
# value never shows up in a process list). Control characters are refused.
json_string() {
  local value="$1"
  if [[ "$value" =~ [[:cntrl:]] ]]; then
    warn "o valor tem um caractere de controle (quebra de linha?); cole de novo."
    return 1
  fi
  value=${value//\\/\\\\}
  value=${value//\"/\\\"}
  printf '"%s"' "$value"
}

# ssm_exists NAME: success when $SSM_PREFIX/NAME exists (value not read).
ssm_exists() {
  aws ssm get-parameter --name "$SSM_PREFIX/$1" --query Parameter.Name --output text >/dev/null 2>&1
}

# ssm_put NAME VALUE: writes the SecureString $SSM_PREFIX/NAME (overwriting).
# The request goes through stdin (--cli-input-json), never through argv.
ssm_put() {
  local name="$1" value json
  value=$(json_string "$2") || return 1
  json=$(printf '{"Name":"%s","Type":"SecureString","Overwrite":true,"Description":"PlantAí API (scripts/aws-after-first-deploy-wizard.sh)","Value":%s}' \
    "$SSM_PREFIX/$name" "$value")
  printf '%s' "$json" | aws ssm put-parameter --cli-input-json file:///dev/stdin >/dev/null
  printf '  %s✓ gravado%s %s/%s (SecureString)\n' "$GREEN" "$RESET" "$SSM_PREFIX" "$name"
}

# stack_status: the stack's status, or NONE when it does not exist.
stack_status() {
  aws cloudformation describe-stacks --stack-name "$STACK" \
    --query 'Stacks[0].StackStatus' --output text 2>/dev/null || echo NONE
}

# stack_resource TYPE LOGICAL_PREFIX: physical id of the stack's resource of
# TYPE whose logical id starts with LOGICAL_PREFIX (empty when missing).
stack_resource() {
  local id
  id=$(aws cloudformation describe-stack-resources --stack-name "$STACK" \
    --query "StackResources[?ResourceType=='$1' && starts_with(LogicalResourceId, '$2')].PhysicalResourceId | [0]" \
    --output text 2>/dev/null || true)
  [[ "$id" == "None" ]] && id=""
  printf '%s' "$id"
}

# dns_records NAME TYPE: the records of NAME as Google Public DNS sees them,
# one per line (TXT without quotes), so the check does not depend on the
# notebook's resolver cache.
dns_records() {
  curl -fsS "https://dns.google/resolve?name=$1&type=$2" 2>/dev/null \
    | grep -oE '"data": ?"([^"\\]|\\.)*"' | sed -E 's/^"data": ?"//; s/"$//; s/\\"//g' || true
}

# subscription_state TOPIC: "<SubscriptionArn> <Endpoint>" of the topic's
# e-mail subscription (SubscriptionArn is PendingConfirmation until clicked).
subscription_state() {
  aws sns list-subscriptions-by-topic --topic-arn "$1" \
    --query "Subscriptions[?Protocol=='email'] | [0].[SubscriptionArn,Endpoint]" --output text 2>/dev/null || true
}

# invoke_task TASK: runs TASK of the maintenance routine synchronously and
# prints its result. Fails when the function returns an error.
invoke_task() {
  local task="$1" meta
  meta=$(aws lambda invoke --function-name "$ROUTINE" --cli-binary-format raw-in-base64-out \
    --payload "{\"task\":\"$task\"}" --query '[StatusCode,FunctionError]' --output text \
    "$WORK_DIR/$task.json")
  note "  resultado: $(cat "$WORK_DIR/$task.json")"
  [[ "$meta" == 200*None* || "$meta" == "200" ]]
}

# api_post PATH: POSTs the JSON read from stdin to the API through its domain
# and prints the HTTP status (the body, tokens included, is discarded).
api_post() {
  curl -s -o /dev/null -w '%{http_code}' -X POST "https://$API_DOMAIN/v1$1" \
    -H 'Content-Type: application/json' --data-binary @- || true
}

TOTAL_STAGES=7

banner "PlantAí · Depois do primeiro deploy: alertas e e-mail de produção"

# ── 1. Tools, account and stack ──────────────────────────────────────────
stage "Ferramentas, conta da AWS e a stack"
say "Confiro as ferramentas, a conta logada e se a stack $STACK já está no ar"
say "(o scripts/aws-first-deploy-wizard.sh vem antes deste)."
printf '\n'
for tool in aws curl; do
  if ! command -v "$tool" >/dev/null 2>&1; then
    warn "$tool não encontrado. Instale e rode de novo."
    exit 1
  fi
done
if [[ "$(aws --version 2>&1)" != aws-cli/2* ]]; then
  warn "precisa do AWS CLI v2 ($(aws --version 2>&1))."
  exit 1
fi
if ! IDENTITY=$(aws sts get-caller-identity --query '[Account,Arn]' --output text 2>&1); then
  warn "o AWS CLI não tem credenciais válidas: $IDENTITY"
  note "Faça login (aws sso login, ou AWS_PROFILE=...) e rode de novo."
  exit 1
fi
printf '  %s✓ AWS%s  conta %s, região %s\n' "$GREEN" "$RESET" "${IDENTITY%%[[:space:]]*}" "$REGION"
note "         ${IDENTITY##*[[:space:]]}"
STATUS=$(stack_status)
if [[ "$STATUS" != CREATE_COMPLETE && "$STATUS" != UPDATE_COMPLETE ]]; then
  warn "a stack $STACK está em $STATUS. Rode antes scripts/aws-first-deploy-wizard.sh"
  note "(ou espere o deploy em andamento terminar)."
  exit 1
fi
API_FUNCTION=$(stack_resource AWS::Lambda::Function ApiFunction)
ROUTINE=$(stack_resource AWS::Lambda::Function MaintenanceRoutineFunction)
TOPIC_ARN=$(stack_resource AWS::SNS::Topic MaintenanceAlerts)
ROUTINE_LOGS=$(stack_resource AWS::Logs::LogGroup MaintenanceRoutineLogs)
API_LOGS=$(stack_resource AWS::Logs::LogGroup ApiLogs)
if [[ -z "$API_FUNCTION" || -z "$ROUTINE" || -z "$TOPIC_ARN" ]]; then
  warn "não achei na stack a função da API, a da rotina ou o tópico de alertas."
  exit 1
fi
printf '  %s✓ stack%s %s: %s\n' "$GREEN" "$RESET" "$STACK" "$STATUS"
note "  API     $API_FUNCTION"
note "  rotina  $ROUTINE"
note "  tópico  $TOPIC_ARN"
printf '\n'
confirm "É nessa conta da AWS que a API está?" || { say "Troque o AWS_PROFILE e rode de novo."; exit 1; }

# ── 2. SNS e-mail subscription ───────────────────────────────────────────
stage "Assinatura de e-mail dos alertas (SNS)"
say "Os alertas (falha da rotina, Neon acima de 80 CU-horas) só chegam depois que"
say "o e-mail do ALERT_EMAIL confirma a assinatura do tópico."
printf '\n'
SUBSCRIPTION=$(subscription_state "$TOPIC_ARN")
SUBSCRIPTION_ARN=${SUBSCRIPTION%%[[:space:]]*}
ALERT_EMAIL=${SUBSCRIPTION##*[[:space:]]}
if [[ "$SUBSCRIPTION_ARN" == arn:* ]]; then
  printf '  %s✓ já confirmada%s %s\n' "$GREEN" "$RESET" "$ALERT_EMAIL"
else
  if [[ "$SUBSCRIPTION_ARN" == PendingConfirmation ]]; then
    warn "a assinatura de $ALERT_EMAIL ainda não foi confirmada."
  else
    warn "o tópico não tem assinatura de e-mail (a AWS apaga as não confirmadas depois de uns dias)."
    ALERT_EMAIL=""
    while [[ ! "$ALERT_EMAIL" =~ ^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$ ]]; do
      ask ALERT_EMAIL "E-mail que recebe os alertas (o mesmo secret ALERT_EMAIL do GitHub):"
    done
  fi
  step "Procure em $ALERT_EMAIL (e no spam) 'AWS Notification - Subscription Confirmation'"
  note "  e clique em 'Confirm subscription'."
  if confirm "Não achou o e-mail ou o link expirou? Pedir à AWS um e-mail novo"; then
    aws sns subscribe --topic-arn "$TOPIC_ARN" --protocol email \
      --notification-endpoint "$ALERT_EMAIL" >/dev/null
    printf '  %s✓ pedido%s confira a caixa de entrada de novo.\n' "$GREEN" "$RESET"
  fi
  while true; do
    SUBSCRIPTION_ARN=$(subscription_state "$TOPIC_ARN")
    SUBSCRIPTION_ARN=${SUBSCRIPTION_ARN%%[[:space:]]*}
    [[ "$SUBSCRIPTION_ARN" == arn:* ]] && break
    printf '\r  %saguardando a confirmação (a cada 15 s)...%s   ' "$DIM" "$RESET"
    sleep 15
  done
  printf '\r\033[K  %s✓ confirmada%s %s\n' "$GREEN" "$RESET" "$ALERT_EMAIL"
fi
printf '\n'
if confirm "Mandar uma mensagem de teste pelo tópico, para ver o alerta chegar?"; then
  aws sns publish --topic-arn "$TOPIC_ARN" --subject "PlantAi: teste dos alertas" \
    --message "Teste do scripts/aws-after-first-deploy-wizard.sh. Se chegou, os alertas chegam." >/dev/null
  printf '  %s✓ publicada%s deve chegar em %s em instantes.\n' "$GREEN" "$RESET" "$ALERT_EMAIL"
  pause "Enter quando tiver chegado (ou para seguir)"
fi
printf '\n'
pause "Enter para continuar"

# ── 3. Maintenance routine, by hand ──────────────────────────────────────
stage "Rotina de manutenção: as duas tarefas na mão"
say "Rodo agora as duas tarefas que o EventBridge Scheduler chama sozinho:"
say "ping-database (toda segunda, 9:00) e check-neon-usage (todo dia, 8:00)."
note "Uma falha aqui dispara o alarme, e o e-mail de erro chega no ALERT_EMAIL."
printf '\n'
ROUTINE_OK=true
for task in ping-database check-neon-usage; do
  step "$task"
  if invoke_task "$task"; then
    printf '  %s✓ sem erro%s\n' "$GREEN" "$RESET"
  else
    printf '  %s✗ falhou%s %s\n' "$RED" "$RESET" "$task"
    ROUTINE_OK=false
  fi
done
if [[ "$ROUTINE_OK" != true ]]; then
  printf '\n'
  say "Últimas linhas do log da rotina ($ROUTINE_LOGS):"
  aws logs tail "$ROUTINE_LOGS" --since 10m --format short 2>/dev/null | tail -n 20 | sed 's/^/    /' || true
  note "Falta de NEON_API_KEY/NEON_PROJECT_ID ou chave recusada: rode o"
  note "scripts/aws-first-deploy-wizard.sh de novo (etapa 4 troca os valores; é ali que a chave"
  note "do Neon é rotacionada) e então este. Os parâmetros novos valem na próxima partida a frio."
  exit 1
fi
note "alerted:false é o esperado enquanto o mês estiver abaixo de 80 CU-horas."
printf '\n'
pause "Enter para continuar"

# ── 4. Resend domain ─────────────────────────────────────────────────────
stage "Resend: domínio $ZONE (registros no subdomínio send.)"
say "Para sair do modo de teste, o Resend precisa do domínio verificado: DKIM em"
say "resend._domainkey e SPF/retorno (MX e TXT) no subdomínio send., no DNS do Registro.br."
printf '\n'
DKIM=$(dns_records "resend._domainkey.$ZONE" TXT)
SEND_MX=$(dns_records "send.$ZONE" MX)
SEND_TXT=$(dns_records "send.$ZONE" TXT)
if [[ "$DKIM" == *p=* && -n "$SEND_MX" && "$SEND_TXT" == *v=spf1* ]]; then
  printf '  %s✓ já no DNS%s DKIM, MX e SPF de send.%s\n' "$GREEN" "$RESET" "$ZONE"
else
  open_url "https://resend.com/domains"
  step "Resend → Domains → Add Domain → nome $ZONE, região North Virginia (us-east-1) → Add."
  note "  (se o domínio já está lá, só abra ele.) O Resend mostra 3 registros, todos com"
  note "  nome relativo a $ZONE: um TXT resend._domainkey, um MX send e um TXT send."
  pause "Enter quando estiver vendo os registros"
  open_url "https://registro.br/painel/"
  step "Painel do Registro.br → domínio $ZONE → DNS → Editar zona → uma Nova entrada para cada:"
  printf '\n    %sTXT%s  Nome resend._domainkey   Dados: o valor p=... que o Resend mostra\n' "$BOLD" "$RESET"
  printf '    %sMX%s   Nome send                Dados: feedback-smtp.<região>.amazonses.com, prioridade 10\n' "$BOLD" "$RESET"
  printf '    %sTXT%s  Nome send                Dados: v=spf1 include:amazonses.com ~all\n\n' "$BOLD" "$RESET"
  note "  Copie os valores do Resend (eles valem sobre os de cima), sem aspas → Salvar."
  note "  Não mexa no CNAME de validação do certificado nem no de $API_DOMAIN."
  pause "Enter quando tiver salvo"
  while true; do
    DKIM=$(dns_records "resend._domainkey.$ZONE" TXT)
    SEND_MX=$(dns_records "send.$ZONE" MX)
    SEND_TXT=$(dns_records "send.$ZONE" TXT)
    [[ "$DKIM" == *p=* && -n "$SEND_MX" && "$SEND_TXT" == *v=spf1* ]] && break
    printf '\r  %sDNS: DKIM %s · MX %s · SPF %s (a cada 30 s)%s   ' "$DIM" \
      "$([[ "$DKIM" == *p=* ]] && echo ok || echo ainda-não)" \
      "$([[ -n "$SEND_MX" ]] && echo ok || echo ainda-não)" \
      "$([[ "$SEND_TXT" == *v=spf1* ]] && echo ok || echo ainda-não)" "$RESET"
    sleep 30
  done
  printf '\r\033[K  %s✓ no DNS%s DKIM, MX e SPF de send.%s\n' "$GREEN" "$RESET" "$ZONE"
fi
note "  MX send.$ZONE: $(tr '\n' ' ' <<<"$SEND_MX")"
printf '\n'
open_url "https://resend.com/domains"
step "No Resend, abra $ZONE → Verify DNS Records (ou espere: ele confere sozinho)."
note "  Os três registros e o domínio precisam ficar 'Verified' (minutos, às vezes mais)."
until confirm "O domínio $ZONE aparece como Verified no Resend?"; do
  note "Espere um pouco e confira de novo. Um registro 'Failed' costuma ser valor colado com aspas"
  note "ou com o domínio repetido no nome (send.$ZONE.$ZONE)."
done
printf '\n'
pause "Enter para continuar"

# ── 5. RESEND_API_KEY and EMAIL_FROM in SSM ──────────────────────────────
stage "SSM: RESEND_API_KEY e EMAIL_FROM de produção"
say "Sem RESEND_API_KEY a API só escreve os e-mails no log; com o domínio verificado,"
say "o remetente passa a ser $EMAIL_FROM_PRODUCTION."
printf '\n'
CHANGED=false
if ssm_exists RESEND_API_KEY; then
  printf '  %s✓ já existe%s RESEND_API_KEY\n' "$GREEN" "$RESET"
  note "  Se ela é 'Full access' ou não está restrita ao domínio, vale trocar por uma nova."
fi
if ! ssm_exists RESEND_API_KEY || confirm "Trocar a RESEND_API_KEY?"; then
  open_url "https://resend.com/api-keys"
  step "Resend → API Keys → Create API key → nome plantai-production,"
  note "  Permission 'Sending access', Domain $ZONE → Add → copie (só aparece uma vez)."
  RESEND_KEY=""
  while true; do
    ask_secret RESEND_KEY "RESEND_API_KEY (escondido):"
    if [[ "$RESEND_KEY" != re_* ]]; then
      warn "as chaves do Resend começam com re_; de novo."
    elif ssm_put RESEND_API_KEY "$RESEND_KEY"; then
      break
    fi
  done
  RESEND_KEY=""
  CHANGED=true
fi
CURRENT_FROM=$(aws ssm get-parameter --name "$SSM_PREFIX/EMAIL_FROM" --with-decryption \
  --query Parameter.Value --output text 2>/dev/null || true)
if [[ "$CURRENT_FROM" == "$EMAIL_FROM_PRODUCTION" ]]; then
  printf '  %s✓ já feito%s EMAIL_FROM = %s\n' "$GREEN" "$RESET" "$CURRENT_FROM"
else
  note "  EMAIL_FROM hoje: ${CURRENT_FROM:-(não existe)}"
  if confirm "Trocar EMAIL_FROM para $EMAIL_FROM_PRODUCTION?"; then
    ssm_put EMAIL_FROM "$EMAIL_FROM_PRODUCTION"
    CHANGED=true
  else
    warn "sem a troca, os e-mails continuam no modo de teste do Resend."
  fi
fi
printf '\n'
pause "Enter para continuar"

# ── 6. Cold start of the API ─────────────────────────────────────────────
stage "Partida a frio da API, para ler o SSM de novo"
say "A função lê o SSM só na partida a frio: as instâncias já quentes seguem com o"
say "remetente antigo. Uma mudança na configuração da função troca todas as instâncias."
printf '\n'
if [[ "$CHANGED" == true ]] || confirm "Nada mudou agora no SSM. Forçar a partida a frio mesmo assim?"; then
  DESCRIPTION=$(aws lambda get-function-configuration --function-name "$API_FUNCTION" \
    --query Description --output text)
  step "Troco a descrição da função e depois volto a original (fica igual ao template da stack)."
  aws lambda update-function-configuration --function-name "$API_FUNCTION" \
    --description "$DESCRIPTION (reload $(date -u +%Y-%m-%dT%H:%M:%SZ))" >/dev/null
  aws lambda wait function-updated-v2 --function-name "$API_FUNCTION"
  aws lambda update-function-configuration --function-name "$API_FUNCTION" \
    --description "$DESCRIPTION" >/dev/null
  aws lambda wait function-updated-v2 --function-name "$API_FUNCTION"
  printf '  %s✓ função atualizada%s as próximas requisições partem a frio.\n' "$GREEN" "$RESET"
fi
CODE=$(curl -s -o /dev/null -w '%{http_code}' "https://$API_DOMAIN/v1/health" || true)
if [[ "$CODE" == 200 ]]; then
  printf '  %s✓ GET https://%s/v1/health → 200%s\n' "$GREEN" "$API_DOMAIN" "$RESET"
else
  warn "GET /v1/health → $CODE. Últimas linhas do log da API ($API_LOGS):"
  aws logs tail "$API_LOGS" --since 10m --format short 2>/dev/null | tail -n 20 | sed 's/^/    /' || true
  exit 1
fi
printf '\n'
pause "Enter para continuar"

# ── 7. A real sign-up ────────────────────────────────────────────────────
stage "Cadastro de teste: o código chega de nao-responda@$ZONE?"
say "Faço um cadastro de verdade na API de produção (POST /v1/auth/signup, o mesmo do"
say "app). Use um e-mail seu; a conta fica de verdade no banco de produção."
note "Se o e-mail já tem conta confirmada, chega o aviso 'você já tem conta', do mesmo remetente."
printf '\n'
SIGNUP_EMAIL=""
while [[ ! "$SIGNUP_EMAIL" =~ ^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$ ]]; do
  ask SIGNUP_EMAIL "E-mail do cadastro:"
done
SIGNUP_PASSWORD=""
while (( ${#SIGNUP_PASSWORD} < 8 )); do
  ask_secret SIGNUP_PASSWORD "Senha da conta (8 ou mais caracteres, escondida):"
done
EMAIL_JSON=$(json_string "$SIGNUP_EMAIL") || exit 1
PASSWORD_JSON=$(json_string "$SIGNUP_PASSWORD") || exit 1
SIGNUP_PASSWORD=""
CODE=$(printf '{"name":"Ângelo","email":%s,"password":%s}' "$EMAIL_JSON" "$PASSWORD_JSON" \
  | api_post /auth/signup)
PASSWORD_JSON=""
if [[ "$CODE" != 202 ]]; then
  warn "POST /v1/auth/signup → $CODE (429 = limite de 3 e-mails em 15 minutos para esse endereço)."
  exit 1
fi
printf '  %s✓ 202%s cadastro aceito, e-mail a caminho de %s\n\n' "$GREEN" "$RESET" "$SIGNUP_EMAIL"
step "Abra a caixa de entrada: o remetente deve ser $EMAIL_FROM_PRODUCTION."
if ! confirm "Chegou de nao-responda@$ZONE?"; then
  say "Linhas do log da API com e-mail nos últimos 10 minutos ($API_LOGS):"
  aws logs tail "$API_LOGS" --since 10m --format short 2>/dev/null \
    | grep -iE 'resend|e-?mail|not sent' | tail -n 20 | sed 's/^/    /' || true
  note "'Not sent (no RESEND_API_KEY)' = a função não leu a chave: rode este wizard de novo."
  note "Erro do Resend sobre o domínio = volte à etapa 4. Confira também o spam."
  exit 1
fi
printf '\n'
SIGNUP_CODE=""
ask SIGNUP_CODE "Código de 6 dígitos, para confirmar a conta (Enter pula):"
if [[ "$SIGNUP_CODE" =~ ^[0-9]{6}$ ]]; then
  CODE=$(printf '{"email":%s,"code":"%s"}' "$EMAIL_JSON" "$SIGNUP_CODE" | api_post /auth/verify-email)
  if [[ "$CODE" == 200 ]]; then
    printf '  %s✓ conta confirmada%s entre no app com esse e-mail e senha.\n' "$GREEN" "$RESET"
  else
    warn "POST /v1/auth/verify-email → $CODE; confirme pelo app, com o código do e-mail."
  fi
fi
printf '\n'
note "Pronto: alertas confirmados, rotina rodando e e-mails saindo de $EMAIL_FROM_PRODUCTION."
note "Para rotacionar a chave do Neon ou outro segredo: scripts/aws-first-deploy-wizard.sh (etapa 4),"
note "depois a etapa 6 deste (partida a frio) ou um deploy."
pause "Enter para o resumo"

finish
